package analysis

// practices_test.go — assertion tables ported from
// tests/unit/test_practices.py, plus golden pins for the unicode-boundary
// traps the RE2 post-filters exist for and byte-exact wire pins generated by
// the Python reference (json.dumps of member_practices over the same items).
// Non-ASCII literals are spelled as escapes so gofmt output stays stable.

import (
	"testing"

	"github.com/yeaboi-ai/yeaboi/go/internal/pysem"
)

// practItem builds an activity item with keys set in the given order.
func practItem(kv ...any) *pysem.Obj {
	o := pysem.EmptyObj()
	for i := 0; i+1 < len(kv); i += 2 {
		o.Set(kv[i].(string), kv[i+1])
	}
	return o
}

// --- TestTicketReference --------------------------------------------------

func TestTicketReference(t *testing.T) {
	cases := []struct {
		name string
		item *pysem.Obj
		want bool
	}{
		{"jira key in title", practItem("kind", "commit", "title", "PAY-123 fix rounding"), true},
		{"azdo ref in body", practItem("kind", "commit", "body", "Fixes AB#42"), true},
		{"azdo ref lowercase", practItem("kind", "commit", "body", "fixes ab#42"), true},
		{"bare issue ref in pr body", practItem("kind", "pr", "body", "Closes #123"), true},
		{"branch reference counts", practItem("kind", "pr", "branch", "feature/ABC-123-login"), true},
		{"branch reference lowercase", practItem("kind", "pr", "branch", "feature/abc-123-login"), true},
		{"utf-8 is not a ticket", practItem("kind", "commit", "title", "encode as UTF-8"), false},
		{"sha-256 is not a ticket", practItem("kind", "commit", "title", "SHA-256 digest"), false},
		{"cve is not a ticket", practItem("kind", "commit", "title", "patched CVE-2024-1234"), false},
		{"gpt-4 is not a ticket", practItem("kind", "commit", "title", "uses GPT-4"), false},
		{"url fragment is not an issue ref", practItem("kind", "commit", "body", "see example.com/a#123 for details"), false},
		{"squash suffix ignored on commits", practItem("kind", "commit", "title", "fix rounding (#123)"), false},
		{"squash suffix counted on prs", practItem("kind", "pr", "title", "fix rounding (#123)"), true},
		{"branch vocabulary is not a ticket", practItem("kind", "pr", "branch", "bugfix-2"), false},
		{"release/v-2 is not a ticket", practItem("kind", "pr", "branch", "release/v-2"), false},
		// Unicode boundaries: Python's \b is unicode, so a word rune like
		// U+00E9 glued to the key kills the boundary at either end.
		{"unicode rune before key kills the boundary", practItem("kind", "commit", "title", "\u00e9PAY-1 fix"), false},
		{"unicode rune after key kills the boundary", practItem("kind", "commit", "title", "fix PAY-12\u00e9"), false},
		{"unicode rune after azdo ref kills the boundary", practItem("kind", "commit", "body", "fixes AB#42\u00e9"), false},
		{"unicode rune after bare ref kills the boundary", practItem("kind", "commit", "body", "closes #12\u00e9"), false},
		// The branch denylist is a computed UNION: branch vocabulary AND the
		// lowercased jira technical tokens both deny.
		{"lowercased jira token denies a branch ref", practItem("kind", "pr", "branch", "hotfix/utf-8"), false},
		{"css token denies a branch ref", practItem("kind", "pr", "branch", "feature/css-12"), false},
		{"branch word denies a branch ref", practItem("kind", "pr", "branch", "sprint-12"), false},
		{"unlisted prefix passes the branch gate", practItem("kind", "pr", "branch", "task/xy-1"), true},
	}
	for _, tc := range cases {
		if got := hasTicketReference(tc.item); got != tc.want {
			t.Errorf("%s: got %v, want %v", tc.name, got, tc.want)
		}
	}
}

// --- TestMeaningfulDescription --------------------------------------------

func TestMeaningfulDescription(t *testing.T) {
	long := ""
	for i := 0; i < 3; i++ {
		long += "This change reworks the rounding logic in the payment engine "
	}
	e120 := ""
	for i := 0; i < 120; i++ {
		e120 += "\u00e9"
	}
	cases := []struct {
		name string
		body string
		want bool
	}{
		{"empty fails", "", false},
		{"whitespace fails", "   \n  ", false},
		{"short one-liner fails", "fix stuff", false},
		{"long paragraph passes", long, true},
		{"two substantial lines pass", "Reworks payment rounding to banker's rounding.\nAdds regression coverage.", true},
		{"markdown checklist passes", "## Changes\n- [x] rounding fix\n- [ ] docs", true},
		// Python len() counts code points, not bytes.
		{"120 two-byte runes pass the long threshold", e120, true},
		{"119 two-byte runes fail the long threshold", e120[:len(e120)-2], false},
	}
	for _, tc := range cases {
		if got := hasMeaningfulDescription(tc.body); got != tc.want {
			t.Errorf("%s: got %v, want %v", tc.name, got, tc.want)
		}
	}
}

// --- TestDocsPath ---------------------------------------------------------

func TestDocsPath(t *testing.T) {
	cases := []struct {
		path string
		want bool
	}{
		{"docs/guide.md", true},
		{"README.md", true},
		{"adr/0001-choice.rst", true},
		{"wiki/setup.adoc", true},
		{"CHANGELOG", true},
		{"DOCS/x.py", true}, // parts are lowercased before matching
		{"src/api.py", false},
		{"tests/test_api.py", false},
		{"lib/readme_parser.py", false},
	}
	for _, tc := range cases {
		if got := isDocsPath(tc.path); got != tc.want {
			t.Errorf("isDocsPath(%q): got %v, want %v", tc.path, got, tc.want)
		}
	}
}

// --- TestMemberPractices --------------------------------------------------

// practicesFixture mirrors tests/unit/test_practices.py::TestMemberPractices
// _items exactly (decoded ordered JSON, as the wire delivers items).
const practicesFixture = `[
  {"kind": "commit", "author": "Ava", "title": "PAY-9 add retries", "body": "",
   "matched_members": ["Ava"], "changed_file_paths": ["src/api.py", "tests/test_api.py"]},
  {"kind": "pr", "author": "Ava", "title": "harden client",
   "body": "Reworks the client retry loop with jitter.\nUpdates the docs for the new flag.",
   "matched_members": ["Ava"], "changed_file_paths": ["src/client.py"]},
  {"kind": "commit", "author": "Ava", "title": "tidy imports", "body": "", "matched_members": ["Ava"]},
  {"kind": "commit", "author": "Ben", "title": "add regression test", "body": "",
   "matched_members": ["Ben"], "changed_file_paths": ["tests/test_edge.py"]},
  {"kind": "pr", "author": "Ben", "title": "quick fix", "body": "",
   "matched_members": ["Ben"], "changed_file_paths": ["src/fix.py"]},
  {"kind": "commit", "author": "devin-ai-integration[bot]", "title": "agent change", "body": "",
   "matched_members": [], "agent_authored": true, "changed_file_paths": ["src/agent.py"]},
  {"kind": "review", "author": "Ava", "title": "LGTM", "body": "", "matched_members": ["Ava"]}
]`

// practicesExpected is json.dumps(member_practices(items, ["Ava", "Ben"]))
// from the Python reference — byte-exact, key order contractual.
const practicesExpected = `{"members": [{"member": "Ava", "commits": 2, "prs": 1, "with_file_data": 2, ` +
	`"tests_num": 1, "tests_den": 2, "tests_rate": 50.0, "docs_num": 1, "docs_den": 2, "docs_rate": 50.0, ` +
	`"ticket_num": 1, "ticket_den": 3, "ticket_rate": 33.3, "desc_num": 1, "desc_den": 1, "desc_rate": 100.0}, ` +
	`{"member": "Ben", "commits": 1, "prs": 1, "with_file_data": 2, "tests_num": 0, "tests_den": 1, ` +
	`"tests_rate": 0.0, "docs_num": 0, "docs_den": 2, "docs_rate": 0.0, "ticket_num": 0, "ticket_den": 2, ` +
	`"ticket_rate": 0.0, "desc_num": 0, "desc_den": 1, "desc_rate": 0.0}, ` +
	`{"member": "AI agent accounts", "commits": 1, "prs": 0, "with_file_data": 1, "tests_num": 0, ` +
	`"tests_den": 1, "tests_rate": 0.0, "docs_num": 0, "docs_den": 1, "docs_rate": 0.0, "ticket_num": 0, ` +
	`"ticket_den": 1, "ticket_rate": 0.0, "desc_num": 0, "desc_den": 0, "desc_rate": null}], ` +
	`"team": {"member": "Team", "commits": 4, "prs": 2, "with_file_data": 5, "tests_num": 1, "tests_den": 4, ` +
	`"tests_rate": 25.0, "docs_num": 1, "docs_den": 5, "docs_rate": 20.0, "ticket_num": 1, "ticket_den": 6, ` +
	`"ticket_rate": 16.7, "desc_num": 1, "desc_den": 2, "desc_rate": 50.0}, ` +
	`"min_sample": 5, "file_data": {"with_file_data": 5, "total": 6}}`

func decodeItems(t *testing.T, doc string) []any {
	t.Helper()
	v, err := pysem.DecodeOrdered([]byte(doc))
	if err != nil {
		t.Fatalf("decode fixture: %v", err)
	}
	items, ok := v.([]any)
	if !ok {
		t.Fatalf("fixture is not a JSON array")
	}
	return items
}

func TestMemberPracticesMatchesThePythonReferenceByteForByte(t *testing.T) {
	items := decodeItems(t, practicesFixture)
	got := pysem.JSONDumps(MemberPractices(items, []string{"Ava", "Ben"}))
	if got != practicesExpected {
		t.Fatalf("wire mismatch:\n got: %s\nwant: %s", got, practicesExpected)
	}
}

func TestZeroDenominatorsGiveNullRates(t *testing.T) {
	items := decodeItems(t, `[{"kind": "commit", "author": "Ava", "title": "loose change", "body": "",
		"matched_members": ["Ava"]}]`)
	want := `{"members": [{"member": "Ava", "commits": 1, "prs": 0, "with_file_data": 0, ` +
		`"tests_num": 0, "tests_den": 0, "tests_rate": null, "docs_num": 0, "docs_den": 0, "docs_rate": null, ` +
		`"ticket_num": 0, "ticket_den": 1, "ticket_rate": 0.0, "desc_num": 0, "desc_den": 0, "desc_rate": null}], ` +
		`"team": {"member": "Team", "commits": 1, "prs": 0, "with_file_data": 0, "tests_num": 0, "tests_den": 0, ` +
		`"tests_rate": null, "docs_num": 0, "docs_den": 0, "docs_rate": null, "ticket_num": 0, "ticket_den": 1, ` +
		`"ticket_rate": 0.0, "desc_num": 0, "desc_den": 0, "desc_rate": null}, ` +
		`"min_sample": 5, "file_data": {"with_file_data": 0, "total": 1}}`
	got := pysem.JSONDumps(MemberPractices(items, []string{"Ava"}))
	if got != want {
		t.Fatalf("wire mismatch:\n got: %s\nwant: %s", got, want)
	}
}

func TestMembersSortByVolumeThenName(t *testing.T) {
	items := decodeItems(t, `[
		{"kind": "commit", "author": "Ben", "title": "", "body": "", "matched_members": ["Ben"]},
		{"kind": "commit", "author": "Ben", "title": "", "body": "", "matched_members": ["Ben"]},
		{"kind": "commit", "author": "Ava", "title": "", "body": "", "matched_members": ["Ava"]}
	]`)
	out := MemberPractices(items, []string{"Ava", "Ben"})
	members := out.Get("members").([]any)
	gotNames := []string{}
	for _, row := range members {
		gotNames = append(gotNames, row.(*pysem.Obj).Get("member").(string))
	}
	if len(gotNames) != 2 || gotNames[0] != "Ben" || gotNames[1] != "Ava" {
		t.Fatalf("got member order %v, want [Ben Ava]", gotNames)
	}
}
